const reduced=matchMedia('(prefers-reduced-motion: reduce)');const dialog=document.querySelector('dialog');let data;const contentReady=fetch('assets/content.json').then(r=>r.json()).then(d=>data=d);document.querySelectorAll('[data-detail]').forEach(b=>b.addEventListener('click',async()=>{await contentReady;const p=data.projects[+b.dataset.detail];const box=dialog.querySelector('.dialog-content');box.replaceChildren();const h=document.createElement('h2');h.textContent=p.short;const text=document.createElement('pre');text.textContent=p.body;box.append(h,text);dialog.showModal()}));dialog.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.querySelectorAll('.project').forEach((p,i)=>p.hidden=b.dataset.filter==='apps'?i>=5:b.dataset.filter==='agents'?i<5:false)});document.querySelectorAll('.media video').forEach(v=>v.addEventListener('play',()=>document.querySelectorAll('.media video').forEach(x=>{if(x!==v)x.pause()})));const hero=document.querySelector('.hero');hero.addEventListener('pointermove',e=>{if(reduced.matches||e.pointerType==='touch')return;hero.style.setProperty('--mx',`${(e.clientX/innerWidth-.5)*22}px`);hero.style.setProperty('--my',`${(e.clientY/innerHeight-.5)*18}px`)});hero.addEventListener('pointerleave',()=>{hero.style.setProperty('--mx','0px');hero.style.setProperty('--my','0px')});window.addEventListener('scroll',()=>document.documentElement.style.setProperty('--progress',`${scrollY/(document.documentElement.scrollHeight-innerHeight)*100}%`),{passive:true});const c=document.querySelector('#orbit'),ctx=c.getContext('2d');let w,h,visible=true,frame;function resize(){w=c.clientWidth;h=c.clientHeight;const d=Math.min(devicePixelRatio,1.5);c.width=w*d;c.height=h*d;ctx.setTransform(d,0,0,d,0,0)}resize();addEventListener('resize',resize);const pts=Array.from({length:260},()=>({a:Math.random()*Math.PI*2,r:.6+Math.random()*.4,s:Math.random()*1.3+.3}));function draw(t=0){ctx.clearRect(0,0,w,h);const angle=reduced.matches?0:t*.000035;ctx.strokeStyle='#d5e8a115';for(let j=0;j<3;j++){ctx.beginPath();ctx.ellipse(w/2,h*.48,w*(.28+j*.05),h*(.18+j*.025),-.25+angle*.1,0,Math.PI*2);ctx.stroke()}for(const p of pts){const a=p.a+angle;const x=w/2+Math.cos(a)*w*.41*p.r,y=h*.48+Math.sin(a)*h*.29*p.r;ctx.fillStyle=`rgba(213,232,161,${.12+(Math.sin(a)+1)*.14})`;ctx.beginPath();ctx.arc(x,y,p.s,0,Math.PI*2);ctx.fill()}if(visible&&!reduced.matches&&!document.hidden)frame=requestAnimationFrame(draw)}new IntersectionObserver(es=>{visible=es[0].isIntersecting;cancelAnimationFrame(frame);if(visible)draw()}).observe(hero);document.addEventListener('visibilitychange',()=>{cancelAnimationFrame(frame);if(!document.hidden&&visible)draw()});reduced.addEventListener('change',()=>{cancelAnimationFrame(frame);draw()});
